"""Date-window membership for the date_window fixture."""

from __future__ import annotations


def _parse_and_validate_date(date_str: str) -> tuple[int, int, int]:
    """Parse and validate an ISO calendar date string (YYYY-MM-DD).

    Returns a tuple of (year, month, day) if valid.
    Raises ValueError if the date is malformed or impossible.
    """
    if not isinstance(date_str, str):
        raise ValueError(f"Date must be a string, got {type(date_str)}")

    # Check format: exactly 10 characters, with dashes at positions 4 and 7
    if len(date_str) != 10 or date_str[4] != '-' or date_str[7] != '-':
        raise ValueError(f"Date must be in YYYY-MM-DD format, got {date_str}")

    # Try to parse components
    try:
        year_str, month_str, day_str = date_str.split('-')
    except ValueError:
        raise ValueError(f"Date must be in YYYY-MM-DD format, got {date_str}")

    # Validate that all parts are exactly the right length (no zero-padding omission)
    if len(year_str) != 4 or len(month_str) != 2 or len(day_str) != 2:
        raise ValueError(f"Date must be in YYYY-MM-DD format with zero padding, got {date_str}")

    # Parse to integers
    try:
        year = int(year_str)
        month = int(month_str)
        day = int(day_str)
    except ValueError:
        raise ValueError(f"Date components must be numeric, got {date_str}")

    # Validate month
    if month < 1 or month > 12:
        raise ValueError(f"Month must be between 1 and 12, got {month} in {date_str}")

    # Validate day based on month and leap year
    def is_leap_year(y: int) -> bool:
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if is_leap_year(year):
        days_in_month[1] = 29

    max_day = days_in_month[month - 1]
    if day < 1 or day > max_day:
        raise ValueError(f"Day {day} is invalid for {year}-{month:02d} in {date_str}")

    return (year, month, day)


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window.

    All dates must be in strict ISO format (YYYY-MM-DD) with proper zero-padding
    and valid calendar dates. Windows are inclusive on both boundaries.
    """
    # Parse and validate the target date
    target = _parse_and_validate_date(target_date)

    # Parse and validate all windows, and check that start <= end for each
    parsed_windows = []
    for start_str, end_str in windows:
        start = _parse_and_validate_date(start_str)
        end = _parse_and_validate_date(end_str)

        # Validate that start <= end
        if start > end:
            raise ValueError(f"Window start {start_str} is after end {end_str}")

        parsed_windows.append((start, end))

    # Check if target falls in any window
    for start, end in parsed_windows:
        if start <= target <= end:
            return True

    return False
